INSERT INTO master.risk_rules (id, business_category_id, risk_type, condition, severity, probability, impact, description, mitigation, source_id, confidence, data_status) VALUES ('RSK-DAIRY-01', 'CAT-DAIRY', 'operational', 'power_outage_risk_high', 'high', 0.65, 'Milk spoilage within 3 hours if chilling fails; potential loss of entire batch value.', 'Rural grid power interruptions can jeopardize bulk milk cooling below critical 4°C threshold.', 'Install dedicated silent diesel generator (min 10 kVA) with automatic changeover switch included in capex.', 'SRC-NABARD-PLP-LDH', 0.94, 'verified') ON CONFLICT (id) DO NOTHING;
INSERT INTO master.risk_rules (id, business_category_id, risk_type, condition, severity, probability, impact, description, mitigation, source_id, confidence, data_status) VALUES ('RSK-DAIRY-02', 'CAT-DAIRY', 'seasonal', 'flush_season_price_drop', 'medium', 0.75, 'Milk supply surge in winter (Nov-Feb) drops spot prices by 10-15%.', 'Winter milk production peaks while summer creates supply deficit.', 'Diversify into long shelf-life cultured products (ghee, paneer) during winter flush months to preserve margin.', 'SRC-PB-DAIRY-BOARD', 0.92, 'verified') ON CONFLICT (id) DO NOTHING;
INSERT INTO master.risk_rules (id, business_category_id, risk_type, condition, severity, probability, impact, description, mitigation, source_id, confidence, data_status) VALUES ('RSK-DAIRY-03', 'CAT-DAIRY', 'regulatory', 'fssai_adulteration_test', 'high', 0.4, 'Fines, license suspension, or product recall if somatic cell/fat content fails standards.', 'FSSAI compliance mandates digital traceability and daily batch testing of raw milk intake.', 'Incorporate ultrasonic milk analyzer testing at intake point and issue payment based on verified Fat/SNF testing.', 'SRC-GOI-DAHD-AHIDF', 0.95, 'official') ON CONFLICT (id) DO NOTHING;
INSERT INTO master.risk_rules (id, business_category_id, risk_type, condition, severity, probability, impact, description, mitigation, source_id, confidence, data_status) VALUES ('RSK-FOOD-01', 'CAT-AGRO-FOOD', 'raw_material_cost', 'wheat_price_volatility', 'high', 0.7, 'Raw wheat price hike reduces chakki milling gross margin by 25-30%.', 'Post-harvest procurement price spikes during off-season (Aug-Dec).', 'Procure 3 months grain stock during peak Rabi harvesting (April-May) using seasonal working capital financing.', 'SRC-PB-MANDI-AGMARK', 0.93, 'verified') ON CONFLICT (id) DO NOTHING;
INSERT INTO master.risk_rules (id, business_category_id, risk_type, condition, severity, probability, impact, description, mitigation, source_id, confidence, data_status) VALUES ('RSK-FOOD-02', 'CAT-AGRO-FOOD', 'competition', 'unorganized_local_mills', 'medium', 0.6, 'Price undercutting by unorganized informal stone mills running on domestic meters.', 'Village-level competitors offering low milling rates without dust extraction or brand value.', 'Brand as 100% stone-ground unadulterated high-fiber atta in moisture-proof vacuum/nitrogen pouches.', 'SRC-GOI-MOFPI-PMFME', 0.9, 'curated') ON CONFLICT (id) DO NOTHING;
INSERT INTO master.risk_rules (id, business_category_id, risk_type, condition, severity, probability, impact, description, mitigation, source_id, confidence, data_status) VALUES ('RSK-CHC-01', 'CAT-FARM-EQUIP', 'seasonal', 'short_operational_window', 'high', 0.85, '70% of machinery demand is concentrated in two 25-day sowing windows (April and October).', 'Paddy transplantation and wheat sowing demand extreme machine uptime.', 'Pre-book farmers with advance discount coupons; offer laser leveling and ditch clearing during off-season months.', 'SRC-NABARD-PLP-LDH', 0.95, 'verified') ON CONFLICT (id) DO NOTHING;
INSERT INTO master.risk_rules (id, business_category_id, risk_type, condition, severity, probability, impact, description, mitigation, source_id, confidence, data_status) VALUES ('RSK-CHC-02', 'CAT-FARM-EQUIP', 'financial', 'diesel_price_escalation', 'medium', 0.65, 'Fuel cost accounts for ~55% of hourly machine operating expense.', 'Diesel price escalations directly erode custom hiring margin.', 'Implement variable hourly fuel escalation clause in farmer service contract agreements.', 'SRC-GRAMVEST-CURATED', 0.91, 'curated') ON CONFLICT (id) DO NOTHING;
INSERT INTO master.opportunity_rules (id, business_category_id, factor, condition, score, reason, source_id, confidence, data_status) VALUES ('OPP-DAIRY-01', 'CAT-DAIRY', 'market_gap', 'village_milk_surplus_over_500lpd_and_no_chiller_within_5km', 85.0, 'High raw milk availability combined with absence of local chilling creates an immediate aggregation opportunity for premium milk sale.', 'SRC-PB-DAIRY-BOARD', 0.92, 'verified') ON CONFLICT (id) DO NOTHING;
INSERT INTO master.opportunity_rules (id, business_category_id, factor, condition, score, reason, source_id, confidence, data_status) VALUES ('OPP-DAIRY-02', 'CAT-DAIRY', 'pricing_arbitrage', 'paneer_raw_milk_spread_over_120rs', 90.0, 'Value-addition conversion of 10 liters buffalo milk (Rs 540) yields 2.2 kg paneer (Rs 726) plus whey, generating 34% higher gross margin.', 'SRC-GRAMVEST-CURATED', 0.93, 'curated') ON CONFLICT (id) DO NOTHING;
INSERT INTO master.opportunity_rules (id, business_category_id, factor, condition, score, reason, source_id, confidence, data_status) VALUES ('OPP-FOOD-01', 'CAT-AGRO-FOOD', 'population_density', 'cluster_households_over_800', 80.0, 'Sufficient local consumption demand (approx 24 quintals atta/month per 100 households) ensures immediate local cash flow.', 'SRC-GOI-CENSUS-2011', 0.9, 'verified') ON CONFLICT (id) DO NOTHING;
INSERT INTO master.opportunity_rules (id, business_category_id, factor, condition, score, reason, source_id, confidence, data_status) VALUES ('OPP-FOOD-02', 'CAT-AGRO-FOOD', 'subsidy_advantage', 'pmfme_eligible_odop_district', 92.0, '35% credit-linked capital subsidy up to Rs 10 Lakh reduces debt service burden and drives positive Year 1 DSCR.', 'SRC-GOI-MOFPI-PMFME', 0.96, 'official') ON CONFLICT (id) DO NOTHING;
INSERT INTO master.opportunity_rules (id, business_category_id, factor, condition, score, reason, source_id, confidence, data_status) VALUES ('OPP-CHC-01', 'CAT-FARM-EQUIP', 'small_farmer_density', 'marginal_cultivators_over_50_percent', 88.0, 'Small and marginal farmers lack capital to purchase tractors; hiring equipment on custom rental is 40% cheaper for them than owning.', 'SRC-NABARD-PLP-LDH', 0.94, 'verified') ON CONFLICT (id) DO NOTHING;
